def transform(grid):
    # Replace the largest solid 1-valued region with 3s, including its enclosed/interior area.
    h, w = len(grid), len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==1 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            comps.append(comp)
    # The pattern changes the broad connected background region, leaving isolated small regions untouched.
    if comps:
        comp=max(comps,key=len)
        out=[row[:] for row in grid]
        for r,c in comp: out[r][c]=3
        return out
    return [row[:] for row in grid]
